class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another.

    Backed by a real OS-level temporary file so that ``fileno()`` returns a
    genuine file descriptor. This allows code under test to pass
    ``sys.stdout``/``sys.stderr`` to APIs such as :func:`subprocess.run` that
    require a real file descriptor, without raising
    :exc:`io.UnsupportedOperation`.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.3
        Backed by a real temporary file so ``fileno()`` works.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._file = tempfile.TemporaryFile()

    def flush(self) -> None:
        super().flush()
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        self._file.write(b)
        return super().write(b)

    def fileno(self) -> int:
        return self._file.fileno()

    def isatty(self) -> bool:
        return False

    def close(self) -> None:
        self._file.close()
        super().close()

